// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    MultiplicatorX3 c;
    function setUp() public { c = new MultiplicatorX3(); }
    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        vm.assume(actor != c.Owner());
        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok;
        try c.Command{value: amount}(address(0xdead), "") {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok);
    }
}
